use std::sync::mpsc;
use std::thread;
use std::time::Duration;

fn main() {
    // ---- Creating a channel ----
    let (tx, rx) = mpsc::channel();

    // ---- Sending messages ----
    thread::spawn(move || {
        let messages = vec![
            String::from("Hello"),
            String::from("World"),
            String::from("From"),
            String::from("Thread"),
        ];

        for msg in messages {
            tx.send(msg).unwrap();
            thread::sleep(Duration::from_millis(200));
        }
    });

    // ---- Receiving messages ----
    for received in rx {
        println!("Received: {}", received);
    }

    // ---- Multiple producers ----
    let (tx2, rx2) = mpsc::channel();
    let tx_clone = tx2.clone();

    thread::spawn(move || {
        for i in 1..=3 {
            tx2.send(i).unwrap();
            thread::sleep(Duration::from_millis(100));
        }
    });

    thread::spawn(move || {
        for i in 4..=6 {
            tx_clone.send(i).unwrap();
            thread::sleep(Duration::from_millis(150));
        }
    });

    for received in rx2 {
        println!("Received from multiple: {}", received);
    }

    // ---- Sending with timeouts ----
    let (tx3, rx3) = mpsc::channel();

    thread::spawn(move || {
        thread::sleep(Duration::from_secs(1));
        tx3.send("Delayed message").unwrap();
    });

    match rx3.recv_timeout(Duration::from_millis(500)) {
        Ok(msg) => println!("Received: {}", msg),
        Err(e) => println!("Timeout: {}", e),
    }

    // ---- Try receiving ----
    let (tx4, rx4) = mpsc::channel();

    match rx4.try_recv() {
        Ok(msg) => println!("Received: {}", msg),
        Err(e) => println!("No message: {}", e),
    }

    // ---- Sending references ----
    let (tx5, rx5) = mpsc::channel();

    thread::spawn(move || {
        let data = vec![1, 2, 3, 4, 5];
        tx5.send(data).unwrap();
    });

    let received_data = rx5.recv().unwrap();
    println!("Received data: {:?}", received_data);
}

